/**
 * One key for a session's menu: a digit "1"…"9" answers the row with that number,
 * "tab" and "shift+tab" are the only other keys, and "submit" presses a
 * multi-select's button. Anything else is refused before the session is looked up.
 * Never a way to type text: words sent to a picker are thrown away and the Return
 * after them confirms whatever is highlighted.
 */
export interface KeyRequest {
  /**
   * The question this answer was chosen for: the SHA-256 (64 lowercase hex digits)
   * of the menu's canonical form, as session.MenuFingerprint and
   * web/console/src/session/fingerprint.ts compute it from the row's menu. When
   * given, nothing is typed unless the question on the session's screen still has
   * this fingerprint; otherwise the answer is refused as menu_moved (a different
   * question, or none) or menu_unreadable (the screen could not be read). Omitted
   * by older pages, which are answered as before on this route; a Cloud answer
   * without it is refused as menu_unverified.
   */
  expect?: string
  key: string
}

export interface LeaseHolder {
  acquired_at: number
  held_seconds: number
  holder: string
  lease_id: string
  liveness: LeaseLiveness

  /**
   * proving, process_running, session_live, heartbeat_lapsed, owner_gone or
   * evidence_unknown.
   */
  liveness_reason: string
  phase?: string
  pid?: number
  reason: string
  renewal_age_seconds: number
  renewed_at: number
  request_id: string
  session_id?: string
}

export interface LeaseList {
  at: number
  leases: LeaseRecord[]
}

export type LeaseLiveness =
    "alive"
  | "gone"
  | "unknown"

export const LeaseLivenessValues: readonly LeaseLiveness[] = ["alive", "gone", "unknown"] as const

/**
 * POST /v1/orchestrator/leases/renew, /release or /cancel.
 */
export interface LeaseOwnerRequest {
  checkout?: string
  phase?: string
  request_id: string
  resource: LeaseResource
}

export interface LeaseRecord {
  holder: LeaseHolder | null
  key: string
  queue: LeaseWaiter[]
  queue_depth: number
  resource: LeaseResource
}

export interface LeaseReply {
  /**
   * queued_behind_others, holder_proving or evidence_unknown.
   */
  hold_reason?: string
  lease: LeaseRecord
  lease_id?: string
  ok: boolean
  position?: number
  retry_after_seconds?: number
  state: string
}

/**
 * POST /v1/orchestrator/leases: ask, or ask again. Idempotent on `request_id`,
 * which is the one proof of ownership. A holder names what proves it alive: a
 * renewal every 20 seconds, `pid` (with `process_start`, epoch seconds),
 * `session_id` (a conversation id), or any of them.
 */
export interface LeaseRequest {
  /**
   * landing only: the absolute path of the checkout being landed into.
   */
  checkout?: string
  holder: string
  phase?: string
  pid?: number
  process_start?: number
  reason?: string
  request_id: string
  resource: LeaseResource
  session_id?: string
}

export type LeaseResource =
    "heavy_compile"
  | "landing"

export const LeaseResourceValues: readonly LeaseResource[] = ["heavy_compile", "landing"] as const

export interface LeaseWaiter {
  holder: string
  pid?: number

  /**
   * Place among the waiters still asking; absent for one that stopped asking and is
   * passed over.
   */
  position?: number
  proving: boolean
  reason: string
  request_id: string
  requested_at: number
  session_id?: string
  waited_seconds: number
}

/**
 * One of the review receipt's three axes, and what it answered.
 */
export interface LedgerAxis {
  axis: string
  findingCount: number

  /**
   * pass or findings.
   */
  status: string
}

/**
 * One Feature's card. `label` when this Mac still remembers what the graph was
 * dispatched for, and null when it does not: the name is swept with the task
 * registry and the id is forever, so the id is sent beside the name rather than
 * replaced by it.
 */
export interface LedgerFeature {
  /**
   * Only on the one-Feature read.
   */
  axes?: LedgerAxis[]
  findings: LedgerFindings

  /**
   * Null on the block that names no Feature, which is the one card on this page
   * whose subject is that there is no Feature.
   */
  graphId: string | null

  /**
   * The findings themselves. Only on the one-Feature read.
   */
  items?: LedgerFinding[]

  /**
   * Null once the destination this graph was dispatched for is no longer on this
   * Mac. A reconstruction would be a guess, and this page's whole subject is that
   * not knowing has to look different from knowing.
   */
  label: string | null

  /**
   * RFC3339. Null when no row or receipt here carried a time.
   */
  lastSeenAt: string | null

  /**
   * Interval rows counted into this card.
   */
  rows: number
  tasks: number
  tokens: LedgerTokens

  /**
   * Only on the one-Feature read.
   */
  verdicts?: LedgerVerdict[]
  verification: LedgerVerification
}

/**
 * One finding, as its review receipt wrote it. The evidence is the passage the
 * finding rests on; a verdict without one is the shape a hallucinating judge
 * produces, which is why the receipt requires at least one.
 */
export interface LedgerFinding {
  evidence: string[]
  findingId: string
  severity: string
  summary: string
}

/**
 * What reviewing this Feature found. `present` with a total of zero is a Feature
 * somebody reviewed and found nothing in, which is the answer worth reaching and is
 * said in those words rather than as `0`.
 */
export interface LedgerFindings {
  /**
   * How many review receipts this figure rests on.
   */
  reviewReceipts: number
  severities: LedgerSeverity[]
  state: LedgerState

  /**
   * Null on every state but `present`, so no reader can put a figure where there is
   * none.
   */
  total: number | null
}

/**
 * What the read reached, and where it stopped. Two ceilings, and they are not the
 * same ceiling: `truncated` is the interval scan reaching its limit, and
 * `featuresListed` short of `featuresFound` is the list itself being cut. A Mac
 * past either reads a number it found over a smaller number it was shown unless
 * both are on the wire.
 */
export interface LedgerRead {
  featuresFound: number
  featuresListed: number

  /**
   * The receipt read reached its ceiling, so the oldest reviews and verifications
   * are not in these figures.
   */
  receiptsTruncated: boolean
  rowsScanned: number

  /**
   * The interval scan reached its ceiling, so older rows are not in these figures.
   */
  truncated: boolean
}

/**
 * How many findings of one severity. Worst first, in the order the route sorted
 * them.
 */
export interface LedgerSeverity {
  count: number

  /**
   * blocking, important or minor: the review receipt's own closed set.
   */
  severity: string
}

/**
 * What a figure is. `present`: it was measured, and the number beside it is the
 * measurement. `absent`: this Mac holds no such receipt — never read as a zero,
 * and never as `nobody did it`, because a receipt whose write failed leaves only a
 * log line. `unknown`: there are rows and not one of them measured anything, which
 * is spending nobody can count.
 */
export type LedgerState =
    "present"
  | "absent"
  | "unknown"

export const LedgerStateValues: readonly LedgerState[] = ["present", "absent", "unknown"] as const

/**
 * One token bucket. A floor and a total are two quantities and both reach the
 * screen: a bucket holding a row that measured only part of what it spent has no
 * total at all, and says so by sending `total: null` beside a `measured` that is
 * still a real number.
 */
export interface LedgerTokenReading {
  /**
   * Rows here that measured only part of what they spent.
   */
  incompleteRows: number

  /**
   * What the rows that did measure add up to. A floor when `total` is null.
   */
  measured: number
  rows: number
  state: LedgerState

  /**
   * Null when the bucket holds a row that measured only part of itself: the figure
   * beside it is a floor, not a total.
   */
  total: number | null
}

/**
 * The token buckets, in the order they are drawn. `undeclared` is a row whose task
 * never said which side of the work it was on, and is never added to the
 * implementation figure beside it: calling it implementation would be a claim about
 * a side that nothing on the row supports.
 */
export interface LedgerTokens {
  implementation: LedgerTokenReading
  review: LedgerTokenReading
  undeclared: LedgerTokenReading
}

/**
 * How many review receipts carried one verdict.
 */
export interface LedgerVerdict {
  count: number

  /**
   * safe_to_land or changes_required: the review receipt's own closed set.
   */
  verdict: string
}

/**
 * What proving this Feature cost, out of the children's own `verification`
 * receipts. Runs and seconds are one sentence on screen, because a run count with
 * no seconds beside it reads as an achievement rather than as a cost.
 */
export interface LedgerVerification {
  /**
   * Receipts whose last run did not pass.
   */
  endedRed: number
  receipts: number
  runs: number
  seconds: number
  state: LedgerState
}

/**
 * What a current inventory says about the bound process. An incomplete reading
 * answers `unknown`, never `offline`: absence of evidence is not proof of death.
 */
export type Liveness =
    "online"
  | "offline"
  | "unknown"

export const LivenessValues: readonly Liveness[] = ["online", "offline", "unknown"] as const

export interface ModelUsage {
  cacheReadTokens: number
  cacheWriteTokens: number
  inputTokens: number

  /**
   * Empty where the record did not name one. Codex's cumulative total does not, and
   * it is left blank rather than guessed from the session's current configuration,
   * which can have changed partway through a thread.
   */
  model: string
  outputTokens: number
  thinkingTokens: number
}

export interface Mover {
  id: string
  kind: MoverKind
}

/**
 * Who can clear an obligation. Naming the mover is what turns a stuck list into an
 * actionable one.
 */
export type MoverKind =
    "this_session"
  | "other_session"
  | "person"
  | "task"
  | "broker"

export const MoverKindValues: readonly MoverKind[] = ["this_session", "other_session", "person", "task", "broker"] as const

export interface Obligation {
  age_seconds: number
  escalation: Escalation
  evidence: Evidence
  id: string
  kind: ObligationKind
  mover: Mover
  note: string
  opened_at: number
  subject: string
}

export type ObligationKind =
    "wait"
  | "landing"
  | "handoff"
  | "succession"
  | "assignment"
  | "deadletter"
  | "review"

export const ObligationKindValues: readonly ObligationKind[] = ["wait", "landing", "handoff", "succession", "assignment", "deadletter", "review"] as const

export interface ObligationList {
  at: number
  obligations: Obligation[]

  /**
   * How many rows are past their overdue threshold. A count, not a verdict.
   */
  stuck: number
}

/**
 * POST /v1/auth/pair/confirm. A wrong code is 403 wrong_code with tries_left. Five
 * wrong codes in a day, whichever pairings they were typed into, close pairing: the
 * fifth, and every confirmation after it, is 403 expired, as are a lapsed pairing
 * and a replaced one.
 */
export interface PairConfirm {
  code: string
  pairing_id: string
}

/**
 * POST /v1/auth/pair. Open without a token. Three in ten minutes, then 429
 * rate_limited; also 429 rate_limited while five wrong codes in the last day keep
 * pairing closed.
 */
export interface PairRequest {
  /**
   * What to call the device; trimmed, at most forty characters, `A browser` when
   * empty.
   */
  name?: string
}

/**
 * The answer to a pairing request. The six-digit code is never in it: it is shown
 * on this machine, to a local-token holder, and typed into the device.
 */
export interface PairStarted {
  /**
   * Unix seconds. Two minutes after the request.
   */
  expires: number
  pairing_id: string
}

export interface PairedDevice {
  /**
   * read, and send when this device may type into a session.
   */
  caps: string[]

  /**
   * Unix seconds.
   */
  created: number
  id: string

  /**
   * Unix seconds of the last request it made since the daemon started or last
   * saved; absent when never.
   */
  last_seen?: number
  name: string
}

/**
 * One `pairing` event on GET /v1/auth/pairings, the server-sent stream only this
 * machine's own token may open. It is the one place the code leaves the daemon. The
 * stream starts with the pairing open now, if any.
 */
export interface PairingNotice {
  code: string
  expires: number
  name: string
  pairing_id: string
}

/**
 * POST /v1/auth/password: a correct password mints a new read-only device. Ten
 * wrong passwords in a day, from everybody together, and the checks still under way
 * count toward the same ten; past it, 429 rate_limited before any hashing. `name`
 * is cut to forty characters before it is stored or audited.
 */
export interface PasswordRequest {
  name?: string
  password: string
}

/**
 * POST /v1/auth/devices/password. Empty clears it. Local token only.
 */
export interface PasswordSet {
  password: string
}

/**
 * One conversation an assistant has already recorded in a place. `id` is the only
 * part a client sends back.
 */
export interface PastSession {
  /**
   * When it was last written to, Unix seconds.
   */
  at: number

  /**
   * A lowercase UUID: the conversation's own id.
   */
  id: string

  /**
   * Something is writing to it right now; resuming it would put a second process on
   * the same record.
   */
  live: boolean
  title: string
}

/**
 * GET /v1/places/{id}/sessions[/{assistant}]: what that assistant has recorded in
 * the place, newest first, at most two hundred. Dispatched children and `-p` runs
 * are not conversations and are left out.
 */
export interface PastSessionList {
  assistant: string
  at: number

  /**
   * The list stopped at its cap and there were more.
   */
  more: boolean
  place: string
  sessions: PastSession[]
}

/**
 * A refusal from the start, resume and history routes: not_found, forbidden,
 * bad_request, invalid_launch, terminal_closed, terminal_unsupported,
 * terminal_io_failed, iterm_attention_required, capability_unavailable,
 * terminal_busy.
 */
export interface PlaceError {
  /**
   * The terminal the refusal is about, on terminal_closed and
   * iterm_attention_required, so a page can name it in its own language.
   */
  app?: string
  code: string
  message: string
  request_id: string
}

export interface PlaceRefusal {
  error: PlaceError
}

/**
 * POST /v1/places/{id}/resume/[{assistant}/]{session}: a conversation this machine
 * listed for that place, picked back up in a new terminal. The same gate and replay
 * as a start.
 */
export interface PlaceResumed {
  assistant: string
  at: number
  attach: string
  backend: Backend
  cwd: string
  id: string
  ok: boolean
  place: string

  /**
   * The conversation that was resumed.
   */
  session: string
}

/**
 * POST /v1/places/{id}/start[/{assistant}[/{model}]]: a terminal was opened and the
 * assistant typed into it. The body is not read. `id` is in the same space as every
 * id in /v1/sessions, but the session is not in that list yet. Needs a device that
 * may send and an Idempotency-Key; a retry within ten minutes is answered from the
 * first reply rather than opening a second tab.
 */
export interface PlaceStarted {
  /**
   * claude or codex, as the path named it (claude when it named none).
   */
  assistant: string
  at: number

  /**
   * What to type at the Mac to see the session, for the one start that puts it
   * where nobody is looking (a tmux server started detached); empty otherwise.
   */
  attach: string
  backend: Backend
  cwd: string

  /**
   * The new terminal: a tmux pane id or an iTerm2 session id.
   */
  id: string

  /**
   * The model the path named, or empty.
   */
  model: string
  ok: boolean
  place: string
}

/**
 * One platform capability on this machine.
 */
export interface PlatformCapability {
  name: PlatformCapabilityName

  /**
   * This machine's sentence: why not, why unknown, or what the capability rests on
   * when it is there.
   */
  reason?: string
  state: PlatformCapabilityState

  /**
   * What provides it here: `tmux`, `iterm`, `pasteboard`, or `shell` for the macOS
   * shell. Absent when nothing does.
   */
  via?: string[]
}

/**
 * `open_child`: open a session for a dispatched child and brief it, in the terminal
 * the machine's `terminal` setting picks. `read_screen`: read what a session's
 * terminal shows. `send_keys`: type into a session. `clipboard`: lend a picture to
 * the system clipboard for a send (without it a send hands over the picture's
 * path). `global_hotkey`: a key that answers wherever the focus is. `notch`: the
 * island around a MacBook's notch. `launch_at_login`: start when the person logs
 * in.
 */
export type PlatformCapabilityName =
    "open_child"
  | "read_screen"
  | "send_keys"
  | "clipboard"
  | "global_hotkey"
  | "notch"
  | "launch_at_login"

export const PlatformCapabilityNameValues: readonly PlatformCapabilityName[] = ["open_child", "read_screen", "send_keys", "clipboard", "global_hotkey", "notch", "launch_at_login"] as const

/**
 * `available`: this machine has it now. `unavailable`: it positively does not, and
 * `reason` says why. `unknown`: whether it does could not be read — never a no.
 */
export type PlatformCapabilityState =
    "available"
  | "unavailable"
  | "unknown"

export const PlatformCapabilityStateValues: readonly PlatformCapabilityState[] = ["available", "unavailable", "unknown"] as const

/**
 * /v1/diagnostics.platform (broker-design #43, cross-platform §5): every platform
 * capability of this machine by name — what it can do, what it cannot and why —
 * each answered from facts that cost nothing to read, without trying any of it.
 * `open_child`, `read_screen` and `send_keys` are what a dispatch needs: one that
 * is `unavailable` refuses a dispatch 409 `no_child_capability` before anything is
 * recorded, naming it, and the refusal carries these same rows. `unknown` is a
 * probe that could not be read, and refuses nothing. Read at the moment of the
 * request, like a dispatch reads it.
 */
export interface PlatformDiagnostics {
  arch: string
  capabilities: PlatformCapability[]

  /**
   * The operating system this daemon runs on, as Go names it: darwin, linux,
   * windows.
   */
  os: string
}

export interface Project {
  displayPath: string
  id: string
  name: string

  /**
   * A reading, not a stored count, so it cannot drift from the thing it describes.
   */
  sessionCount: number
}

export interface ProjectCatalog {
  /**
   * False when the store could not be read at all; `readState.error` says why.
   */
  available: boolean

  /**
   * The store's own Board switch.
   */
  enabled: boolean
  mode: string
  projects: CatalogProject[]
  readState: CatalogReadState
  revision: number
  schemaVersion: number
  source: CatalogSource
}

/**
 * GET /v1/projects.
 */
export interface ProjectCatalogAnswer {
  at: number
  catalog: ProjectCatalog
}

/**
 * What the workflow file said on a beat it drew no row. `repository: github`
 * answers that a run *could* be named; this answers what was found under that name,
 * so that no deploy row stops being one silence and becomes the sentence the file
 * already contains. Present only with `repository: github`, and absent whenever a
 * deploy row was drawn.
 */
export interface ProjectDeployQuiet {
  kind: ProjectDeployQuietKind

  /**
   * The producer's own state word, verbatim and untranslated — `none` where it
   * had nothing to say, and whatever else it writes. Absent with `no_file` and
   * `unreadable`, where nothing was read.
   */
  state?: string

  /**
   * The file's own `updated_at`, in seconds since 1970, which is a different moment
   * from `observedAt`: this is when that tool last decided, `observedAt` is when
   * this walk read what it decided. A reason written three days ago is a poller
   * that stopped, not a project that has nothing to show, and nothing else on this
   * wire can tell those apart. Absent where the file carried no `updated_at` or
   * none was read.
   */
  updatedAt?: number

  /**
   * The producer's own reason, verbatim and untranslated, from the file's `why`.
   * **This vocabulary is not this daemon's and is not closed**: the tool that
   * writes `~/.claude/statusline-cache/` chooses these words, and a reader that
   * carried only the ones it already knew would go silent again the first time that
   * tool learned a new one — which is the whole shape this field exists to end. A
   * reader turns the ones it knows into a sentence and says the rest as the words
   * they are. Absent when the file carried none.
   */
  why?: string
}

/**
 * Which kind of silence a workflow file kept. `no_file`: nothing has written one
 * for this repository, so there is no deploy row because nobody looked and not
 * because there is no run. `unreadable`: a file is there and could not be read as
 * one small JSON object. `state_not_drawn`: it was read and says a state no reader
 * here draws — `none` is what a producer with nothing to say writes, and a dot
 * drawn for it would be the always-wrong mark. `no_address`: it names a run and no
 * page to open it on, and a row with nowhere to go is not a row. Four words because
 * what to do about each is different: start the poller, look at the file, read
 * `why`, look at the producer.
 */
export type ProjectDeployQuietKind =
    "no_file"
  | "unreadable"
  | "state_not_drawn"
  | "no_address"

export const ProjectDeployQuietKindValues: readonly ProjectDeployQuietKind[] = ["no_file", "unreadable", "state_not_drawn", "no_address"] as const

/**
 * Which way the git read failed, present only with `unreadable`. Four words because
 * what to do about each is different: install git, wait, look at the repository.
 */
export type ProjectGitFailure =
    "git_missing"
  | "git_timeout"
  | "git_failed"
  | "git_answer_too_large"

export const ProjectGitFailureValues: readonly ProjectGitFailure[] = ["git_missing", "git_timeout", "git_failed", "git_answer_too_large"] as const

/**
 * One address a project has. `kind` says which of the walk's sources it came from
 * and decides how a reader draws it; `state` is the colour of its dot, `status` the
 * producer's own word for the same thing, and `why` one line saying what is wrong
 * when something is.
 */
export interface ProjectLink {
  /**
   * `deploy` is a workflow run named after the repository's GitHub remote; `run` is
   * a test or build on this machine; `server` is a process a `.devstack.json`
   * declares; anything else is a health check, named by the receipt itself (`site`
   * when it named none, `ci` where a receipt says so). The status-line chip draws
   * `run`, `deploy` and `ci`.
   */
  kind: string

  /**
   * What the row is called: the producer's own label, or the reader's word for that
   * kind when the file named none.
   */
  label: string

  /**
   * The address is on this machine's own network, so a paired phone cannot follow
   * it.
   */
  local: boolean

  /**
   * Producer text for what a local run is doing now — `compiling`. Drawn
   * verbatim, in every language, in place of the percentage: the bar already says
   * how far along this is, and this answers the question a percentage cannot.
   */
  phase?: string

  /**
   * Unix seconds this run began. Only on a `running` row, and only where the
   * producer wrote it: a progress bar drawn from a missing number is a bar that
   * lies, so a reader with neither this nor `typicalSeconds` draws an indeterminate
   * one.
   */
  startedAt?: number

  /**
   * The dot: `ok`, `down`, `fail`, `running`, or empty when nothing measured it —
   * which on a `server` row is said by `unknownReason` rather than drawn as a
   * colour, because a red dot nobody measured is a mark that is always wrong.
   */
  state: string

  /**
   * The producer's own word, kept beside the dot where the two vocabularies differ:
   * `not deployed` and `unreachable` are both a red dot and are not the same fact.
   * Absent when the state is all there was.
   */
  status?: string

  /**
   * How long this run usually takes, as the producer measured it. Only on a
   * `running` row.
   */
  typicalSeconds?: number
  unknownReason?: ProjectServerUnknown

  /**
   * Where it opens. Absent on a local run, whose log is a filesystem path rather
   * than an address — the one row here with nowhere to go. A reader turns only
   * `http(s)://` into an anchor.
   */
  url?: string

  /**
   * One line saying what is wrong, from the producer: a health receipt's `reason`.
   * Absent when nothing is wrong or nothing said.
   */
  why?: string
}

/**
 * GET /v1/sessions/{id}/links. Served from a maintained projection per working
 * directory: a held reading comes back however old it is and a refresh is taken
 * behind the request, because a link row that is thirty seconds old is a correct
 * answer to 'where can I go from here' and a spinner is not. Only the first read
 * for a directory is synchronous. This is never on the session list and never on
 * the event stream — the walk costs a subprocess, and paying for it per session
 * per beat is what the Swift app's route comment refuses.
 */
export interface ProjectLinksReply {
  deployQuiet?: ProjectDeployQuiet
  links: ProjectLink[]

  /**
   * When this walk was taken, in seconds since 1970. It travels with the rows so a
   * reader can say how old they are; nothing here decides that for it.
   */
  observedAt: number
  repository: ProjectRepository

  /**
   * More rows were found than one answer carries, and the rest are not in `links`.
   * Absent when nothing was left out.
   */
  truncated?: boolean
  unreadable?: ProjectGitFailure
}

/**
 * What the one git read found, which is a different question from what it produced.
 * A deploy row is a file named after the repository's GitHub remote, so four of
 * these five answers produce no deploy row — and only `unreadable` leaves it
 * unknown whether there was one to produce. They are separate words because 'could
 * not read' and 'there is none' must not be one sentence on a screen.
 */
export type ProjectRepository =
    "github"
  | "remote_not_github"
  | "no_remote"
  | "not_a_repository"
  | "unreadable"

export const ProjectRepositoryValues: readonly ProjectRepository[] = ["github", "remote_not_github", "no_remote", "not_a_repository", "unreadable"] as const

/**
 * Why a `server` row has no state. `status_not_run`: the project declares a status
 * command and this daemon runs no command a repository names, so only a declared
 * port could have been asked and there was none. `nothing_declared`: the file
 * declares no port at all. Absent wherever a state was measured, because a dot
 * nobody measured is a mark that is always wrong.
 */
export type ProjectServerUnknown =
    "status_not_run"
  | "nothing_declared"

export const ProjectServerUnknownValues: readonly ProjectServerUnknown[] = ["status_not_run", "nothing_declared"] as const

/**
 * Which worktrees under one Project finished a Feature. With no accepted Feature
 * attribution on this daemon, `worktrees` is always empty; the read still resolves
 * the Project.
 */
export interface ProjectWorktrees {
  excluded: ProjectWorktreesExcluded
  generatedAt: string
  outcomeRule: string
  policy: string
  project: ProjectWorktreesProject
  range: AnalyticsRange
  read: ProjectWorktreesRead
  schemaVersion: number

  /**
   * available or partial.
   */
  status: string
  unattributed: ProjectWorktreesUnattributed

  /**
   * Per-worktree outcomes (open objects).
   */
  worktrees: AnalyticsCounts[]
}

/**
 * Worktrees left out for having no accepted Feature.
 */
export interface ProjectWorktreesExcluded {
  reason: string
  worktreesWithoutFeature: number
}

/**
 * The Project resolved.
 */
export interface ProjectWorktreesProject {
  id: string
  label: string
}

/**
 * What a project-worktrees read covered.
 */
export interface ProjectWorktreesRead {
  featureRows: number
  maxScannedRows: number
  projectRows: number
  rows: number
  truncated: boolean
  worktreeRows: number
}

/**
 * GET /v1/orchestrator/usage/project-worktrees.
 */
export interface ProjectWorktreesReply {
  projectWorktrees: ProjectWorktrees
}

/**
 * Managed worktrees whose rows name no Project.
 */
export interface ProjectWorktreesUnattributed {
  reasons: AnalyticsCounts
  worktrees: number
}

/**
 * /v1/diagnostics.proposals (design-decisions T4, board-redesign §4.4): what the
 * server decided about asking a person in the conversation, and what the sessions
 * reported doing, counted from the proposals table — durable, the same after a
 * restart. `ask_true` is the proposals the server let be asked; `asked_inline` the
 * ones a session reported asking; `asked_inline_unprompted` those of them the
 * server had said not to ask, which is a briefing not followed. `matched` is
 * `asked_inline == ask_true` with none unprompted; an ask a session has not
 * reported yet also reads as unmatched.
 */
export interface ProposalDiagnostics {
  ask_false: number
  ask_true: number
  asked_inline: number
  asked_inline_unprompted: number

  /**
   * The counts could not be read; every number beside it is zero and means nothing.
   */
  error?: string
  matched: boolean

  /**
   * When the proposal waiting longest was made. Absent when none waits.
   */
  oldest_pending_at?: number

  /**
   * Proposals waiting for an answer: the "to confirm" area and the ones asked in a
   * conversation.
   */
  pending: number
}

/**
 * GET /v1/push/key. The application server key the page passes to `subscribe({
 * applicationServerKey })`: base64url of the uncompressed P-256 public point. It is
 * an identity rather than a session — every subscription a browser makes is bound
 * to it, so minting a new one silently unsubscribes every device.
 */
export interface PushKey {
  key: string
}

/**
 * A push route that has nothing to report but that it did the thing.
 */
export interface PushOK {
  ok: boolean
}

/**
 * What a send actually achieved. `sent` is push services that accepted, `failed` is
 * every other outcome including a subscription that was dropped as gone — a route
 * that promised content to a person must not confuse 'the send was started' with 'a
 * service accepted it'.
 */
export interface PushSent {
  failed: number
  ok: boolean
  sent: number
}

/**
 * POST /v1/push/subscribe. The subscription goes up exactly as the browser wrote it
 * — anything reshaped on the way is a chance to get a credential wrong. It is
 * validated rather than stored as given: `endpoint` is a URL this machine will POST
 * to from inside its own network whenever a session changes, so an unchecked one is
 * a request-forgery primitive handed to whoever holds a token.
 */
export interface PushSubscribeRequest {
  /**
   * https only, and a real host. Not an allowlist of vendors: Apple, Mozilla,
   * Google and anything self-hosted all have to work.
   */
  endpoint: string
  keys: PushSubscriptionKeys
}

/**
 * What subscribing answers. `id` is this machine's name for the row, and the page
 * keeps it so it can take the subscription back after a reload.
 */
export interface PushSubscribed {
  id: string
  ok: boolean
}

/**
 * The browser's half of the encryption, exactly as `PushSubscription.toJSON()`
 * wrote it. `p256dh` is a public key and `auth` is a secret this machine cannot use
 * to read anything, only to write to that one device.
 */
export interface PushSubscriptionKeys {
  /**
   * base64url of 16 octets, RFC 8291 §3.2.
   */
  auth: string

  /**
   * base64url of an uncompressed P-256 point: 65 octets starting 0x04.
   */
  p256dh: string
}

/**
 * POST /v1/push/test. Reaches the asking device and nothing else: a test whose
 * blast radius is larger than the thing being tested teaches you to be careful with
 * it, which is the opposite of what a test button is for. `session_id` is optional
 * and is what turns a light into a loop — without it the button answers half a
 * question (did a notification arrive) and the half that actually goes wrong is the
 * other one (does tapping one get me back to my session).
 */
export interface PushTestRequest {
  session_id?: string
}

/**
 * POST /v1/push/unsubscribe. The id this machine gave back when the browser
 * subscribed.
 */
export interface PushUnsubscribeRequest {
  id: string
}

/**
 * Every refusal on this daemon has this shape. A caller reads `error` as the code
 * and never parses `detail`.
 */
export interface Refusal {
  detail: string
  error: string
  route?: string
  upstream?: string
}

/**
 * POST /v1/auth/devices/revoke-all: every paired device, the password and the open
 * pairing. This machine's own token stays.
 */
export interface RevokedAll {
  count: number
  ok: boolean
}

/**
 * A broker-proved independent Feature Root this session owns.
 */
export interface RootAssignmentRecord {
  explanation: string
  id: string
  label: string
  ownership: string
  state: string
}

/**
 * What the reading behind this snapshot knows about itself. Without it an empty
 * list cannot be told apart from a failed scan.
 */
export interface Scan {
  complete: boolean
  completed: ScanCompleted

  /**
   * An empty list is only authoritative when the reading was complete. This is what
   * stops a client reading a failed scan as `every session went away`.
   */
  emptyAuthoritative: boolean

  /**
   * Identifies the process. A client reconnecting to a restarted daemon uses it to
   * tell a reset generation from one that went backwards.
   */
  epoch: number
  generation: number
  provenance: string

  /**
   * Each source's own completeness, by provenance name, in a stable order.
   * Optional: a reading with no per-source answer omits it, and a client written
   * before it existed is unaffected.
   */
  sources?: ScanSource[]
}

export interface ScanCompleted {
  complete: boolean
  sequence: number
}

/**
 * One region of a source that this reading could not see into, named. A source that
 * says only `incomplete` has told a reader that its list is short and nothing else,
 * so every absence on the machine becomes unprovable at once — including absences
 * that source was never asked about. Naming the region lets a reader ask the
 * narrower question instead: could what I am looking for be in the part that was
 * not read?
 */
export interface ScanGap {
  /**
   * What was asked and what came back, in one sentence, for a person reading it.
   */
  detail: string

  /**
   * The region's own id, where the source can name one. Absent when it could not,
   * and a region with no name is never sealed.
   */
  id?: string

  /**
   * The kind of region, in the source's own words: `window`.
   */
  scope: string

  /**
   * Another source has accounted for everything this region could be hiding, so it
   * no longer costs its source its authority. Time never sets this: a window unread
   * for two hours is a window unread, and `long enough` is the same guess made more
   * slowly.
   */
  sealed: boolean

  /**
   * That reason with its numbers in it, so a reader can check it rather than take
   * it. Absent on a region that is still open.
   */
  sealedBy?: string
}

/**
 * One source's own answer about itself. The merged `complete` is the AND of these,
 * which is the right answer to `is this list all there is` and the wrong one to `is
 * this pane gone`: only the source that reads panes can say that. A reader that
 * must decide whether a session it remembers is really absent asks the source that
 * would have seen it.
 */
export interface ScanSource {
  complete: boolean

  /**
   * The regions of this source that could not be read, each one either sealed by
   * another source or still open. Optional: a source that read everything omits it.
   * A person whose machine has gone quiet reads this to find out what is in the
   * way.
   */
  gaps?: ScanGap[]

  /**
   * The source's provenance, as the adapter names it: `ps`, `tmux`, `iterm`.
   */
  source: string
}

export interface ScheduleDeleted {
  deleted: string
  ok: boolean
}

export interface ScheduleDetail {
  schedule: ScheduleRecord
}

export interface ScheduleLastRun {
  /**
   * When the run's task was created, Unix seconds.
   */
  at: number

  /**
   * The task's state: queued, spawning, briefed, success, failure, timeout,
   * cancelled or spawn_failed.
   */
  state: string
  task_id: string
}

export interface ScheduleList {
  at: number
  schedules: ScheduleRow[]
}

/**
 * GET /v1/orchestrator/schedules/:id: one schedule in full — the template and the
 * retained runs the list leaves out. `webhook_binding_availability` is `active`
 * (with `webhook_hook_id`), `unbound`, or `binding_store_unavailable`.
 */
export interface ScheduleRecord {
  catch_up_hours: number
  close_tab: string
  enabled: boolean
  file: string
  fired_at?: number
  id: string
  last_missed_at?: number
  last_run?: ScheduleLastRun
  next_fire?: number
  notify_on_failure: boolean
  once?: boolean
  runs: ScheduleRun[]
  runs_may_be_truncated?: boolean
  task: ScheduleTask
  title: string
  webhook_binding_availability: string
  webhook_hook_id?: string
  when: ScheduleWhen
}

/**
 * The body POST /v1/orchestrator/schedules and PATCH /v1/orchestrator/schedules/:id
 * take — the form's fields, flattened. `place_id` is an id from GET /v1/places,
 * never a path. Exactly one of `days` and `on`; `days` is not defaulted.
 * schedule_id, created_at, when_changed_at, fired_at and project_dir are the
 * machine's and are refused as unknown fields. Writes need an Idempotency-Key and
 * either a device that may send or, for a schedule that runs once, this machine's
 * orchestrator token.
 */
export interface ScheduleRequest {
  assistant: string
  at: string
  catch_up_hours?: number
  close_tab?: string
  days?: string[]
  enabled?: boolean
  instructions: string

  /**
   * No key leaves the model alone; an empty string takes it off.
   */
  model?: string
  notify_on_failure?: boolean
  on?: string
  place_id: string
  timeout_minutes?: number
  title: string
}

/**
 * One row of the list, in one of two shapes. A valid schedule carries id, title and
 * enabled, and whichever of the rest apply. A schedule this daemon cannot parse
 * carries only file, state (`invalid`), error and error_kind (`schema`,
 * `project_unavailable` or `unreadable_json`) — it is listed rather than hidden,
 * because a row that vanishes is a row nobody can fix. No task-template field is
 * listed but project_dir.
 */
export interface ScheduleRow {
  enabled?: boolean
  error?: string
  error_kind?: string
  file?: string

  /**
   * A schedule that runs once, and has: when its session opened. Such a schedule
   * never fires again.
   */
  fired_at?: number
  id?: string

  /**
   * The most recent occurrence that expired outside its catch-up window.
   */
  last_missed_at?: number
  last_run?: ScheduleLastRun

  /**
   * The next local fire, Unix seconds. Absent for a schedule that will not fire
   * again.
   */
  next_fire?: number

  /**
   * Present and true for a schedule that runs once (`when.on`).
   */
  once?: boolean
  project_dir?: string

  /**
   * `invalid` on a row that could not be parsed; absent otherwise.
   */
  state?: string
  title?: string
}

/**
 * One task a schedule made, newest first in the detail. `summary` is what the task
 * wrote when it finished.
 */
export interface ScheduleRun {
  assistant: string
  created: number
  finished_at?: number
  project_dir: string
  session_id?: string
  state: string
  summary?: string
  task_id: string
  terminal_id?: string
}

/**
 * A made or saved schedule. `dispatch_enabled` rides beside a made one only:
 * writing a schedule is not dispatching, and with task dispatch switched off
 * nothing runs it.
 */
export interface ScheduleSaved {
  dispatch_enabled?: boolean
  ok: boolean
  schedule: ScheduleSummary
}

export interface ScheduleSummary {
  enabled: boolean
  id: string
  next_fire?: number
  title: string
}

/**
 * The task template, as the file carries it. The fields a request may never name
 * — project_dir, claims, permission_mode and the rest — are set in the file and
 * carried across every save.
 */
export interface ScheduleTask {
  assistant: string
  claims?: string[]
  deliverables?: string[]
  instructions: string
  isolation?: string
  isolation_base?: string
  kind?: string
  model?: string
  permission_mode?: string
  plan?: string
  project_dir: string
  reasoning_effort?: string
  serialize?: string[]
  timeout_minutes?: number
  title?: string
}

/**
 * `when` in the file's own spelling: `at` (HH:MM, local time) and exactly one of
 * `days` (`daily`, or weekday names sun…sat) or `on` (YYYY-MM-DD, a schedule that
 * runs once).
 */
export interface ScheduleWhen {
  at: string
  days?: string[]
  on?: string
}

/**
 * What the clock says about its own last pass. A pass that fired nothing and a
 * scheduler that stopped are both silence from outside, so the clock reports itself
 * the way a scan does.
 */
export interface SchedulerPulse {
  /**
   * When the last pass ran. Absent means no pass has finished yet, which is the
   * ordinary state for the first tick after startup.
   */
  at?: number
  considered: number

  /**
   * How many came due on this pass. Separate from `fired` because a due schedule
   * whose dispatch was refused is not the same as nothing being due.
   */
  due: number
  fired: number

  /**
   * Why a pass did nothing, when the reason was not that nothing was due.
   */
  note?: string
  tickSeconds: number
}

/**
 * One reading of a terminal. `backend` and `channel` come first because a screen
 * with no backend named is the defect this exists to avoid, and `lines` is what
 * came back rather than what was asked for: an alternate-screen program has no
 * history to give and this must not imply otherwise.
 */
export interface Screen {
  /**
   * On `on-demand` only, said out loud rather than left for the client to discover:
   * nothing will tell it the screen moved, so asking again is the only way to see a
   * change, and this is the fastest it may.
   */
  askAgainAfterMs?: number

  /**
   * Unix seconds of the capture this text came from.
   */
  at?: number
  backend: Backend
  captures: number
  channel: ScreenChannel
  id: string

  /**
   * How many rows actually came back. The trailing newline a capture ends with is a
   * terminator, not a row.
   */
  lines?: number

  /**
   * Nothing has been captured for this session yet. The first read of a session
   * answers this and the screen arrives a few milliseconds later on the `screen`
   * event, because the answer comes out of a published snapshot and the capture
   * happens behind it.
   */
  pending: boolean
  readable: boolean

  /**
   * What a client compares to decide whether it already has this screen. FNV-1a
   * over the UTF-8 bytes, which is enough for "did these change" and is
   * deliberately not a promise about anything else. An unreadable screen is the
   * constant `unreadable`, so a pane that stays unreadable stops producing events
   * after the first one.
   */
  revision: string
  signals: number

  /**
   * The capture, escape sequences kept. Absent until the first one completes.
   */
  text?: string

  /**
   * Unix seconds. The lease this read renewed; a lease nobody renews expires and
   * takes the pipe with it.
   */
  watchingUntil: number
}

export interface ScreenAnswer {
  screen: Screen
}

/**
 * How a watcher finds out that a screen changed, which is a fact about the backend
 * and not about the watcher. `signalled` is tmux with a pipe on the pane, about
 * four milliseconds behind it; `on-demand` is a sample taken when somebody asks, no
 * faster than `askAgainAfterMs`. Drawing the two identically would be a lie the
 * reader has no way to catch, so it is in every payload.
 */
export type ScreenChannel =
    "signalled"
  | "on-demand"

export const ScreenChannelValues: readonly ScreenChannel[] = ["signalled", "on-demand"] as const

/**
 * The `screen` frame on /v1/events: only that a screen moved, and to what revision.
 * The screen itself is fetched through the authenticated GET, exactly as a
 * transcript append is — a stream frame reaches every device on this connection,
 * and a terminal somebody else is watching has no business on it.
 */
export interface ScreenEvent {
  at: number
  id: string
  revision: string
}

/**
 * The machine state this feature creates, published so that somebody can see it.
 * `tmux list-panes -a -F '#{pane_id} #{pane_pipe}'` answers the same question in
 * one command; this answers it and says which of those pipes this daemon can
 * account for, which tmux cannot, because `#{pane_pipe}` is a boolean with no owner
 * in it. A pane that is piped and not on this daemon's list is therefore
 * `unattributed` rather than a leak, and nothing here takes somebody else's pipe
 * off.
 */
export interface ScreenInventory {
  attached: string[]
  leaseSeconds: number
  piped: string[]
  screens: ScreenWatch[]
  unattributed: string[]
  windowMs: number
}

/**
 * One row of what this daemon is watching.
 */
export interface ScreenWatch {
  backend: Backend
  captures: number
  channel: ScreenChannel
  expiresIn: number
  id: string
  readable: boolean

  /**
   * Whether this daemon has a pipe on that pane right now.
   */
  signalled: boolean
  signals: number
  watching: boolean
}

/**
 * Text, pictures, or both; a send that is neither is refused. Each picture is a
 * base64 `data:` URL, at most six, inside the 20 MB body limit. Pictures that
 * cannot be decoded are left out, and a send none of whose pictures can be is
 * refused.
 */
export interface SendRequest {
  images?: string[]
  text?: string
}

/**
 * When this session last moved, from this daemon rather than from whatever each
 * browser happened to have watched: the moment the session's own conversation
 * record last grew. That one file follows both halves of a turn — the assistant
 * appends its output to it and the person's message is appended to it too — so it
 * is the single answer to a question that otherwise splits into three that
 * disagree. State changes are not it: a session working since midnight changes
 * state twice a night, and ordering by that would sink it below one that blinked an
 * hour ago. The list orders by this inside each state, so an assistant still
 * producing output at four in the morning reads as moving now, and a session
 * somebody replied to ten minutes ago and which has gone quiet reads as ten minutes
 * old and sits above one that stopped at midnight. Absent on a row no reading has
 * answered for.
 */
export interface SessionActivity {
  /**
   * Unix seconds: when the record last grew. Present only when `known`.
   */
  at?: number

  /**
   * This machine's own sentence about the answer, for a reader deciding whether to
   * wait, fix this machine or stop asking.
   */
  detail?: string
  evidence?: Evidence

  /**
   * Whether there is a time. False is a real answer and carries `unknown_reason`: a
   * client must draw it as unknown and order it ahead of every known time inside
   * its state, never as a very old time. Of the two ways to be wrong about a row
   * nobody could read, only `it has been quiet for a week` hides the row somebody
   * has to act on.
   */
  known: boolean
  unknown_reason?: ActivityUnknownReason
}

/**
 * Who this session is parked on, and who is parked on it. Absent when neither.
 * `state` is `waiting_on_session` whenever `waitingOn` is not empty, otherwise
 * `has_waiters`.
 */
export interface SessionCoordination {
  state: string
  waitedOnBy: CoordinationWaitRow[]
  waitingOn: CoordinationWaitRow[]
}

/**
 * Present on exactly the row whose live process is the one
 * ~/.config/clawdline/coordinator.json registers — terminal, assistant, tty, pid,
 * start time and conversation all equal. `status` is always `online` here, because
 * the field is only attached to a matching live row.
 */
export interface SessionCoordinator {
  commands: SessionCoordinatorCommand[]
  label: string
  status: string
}

/**
 * One command in the Clawdfather panel. The list is the Swift app's fixed table
 * (Coordinator.swift `commands`), in its order. `reason` and `why` are present only
 * when `enabled` is false.
 */
export interface SessionCoordinatorCommand {
  enabled: boolean
  reason?: string
  token_effort: string
  token_effort_basis: string
  type: string
  why?: string
}

/**
 * The facts behind the status line under an open session. This daemon serves the
 * transcript-derived part the Swift app calls the summary, the context reading, the
 * plan windows and the project's addresses; the working tree, permission and fast
 * mode are not read here and their keys are absent.
 */
export interface SessionInfo {
  context?: SessionInfoContext

  /**
   * The `links` rows whose kind is `deploy`, `ci` or `run`, unchanged, so a state
   * means there what it means there. It is the smaller field the Swift app kept for
   * older clients, and the one the status line's chip is drawn from.
   */
  deploy?: ProjectLink[]

  /**
   * Why a repository that *is* on GitHub still has no deploy row here. `repository:
   * github` says a workflow run could have been named; this says what was found
   * under that name and, where the file gave one, the producer's own reason for
   * having nothing to show. Without it a project with a wedged poller and a project
   * between runs are one blank cell.
   */
  deployQuiet?: ProjectDeployQuiet
  limits?: SessionLimits

  /**
   * Where this project can be opened, the same rows GET /v1/sessions/{id}/links
   * answers with (links.schema.json). Served from the same maintained projection,
   * so the card and the sheet cannot show one project two ways. Absent when the
   * session has no working directory.
   */
  links?: ProjectLink[]

  /**
   * When the walk behind `links` was taken, in seconds since 1970. A held reading
   * is served however old it is, so a card that wants to say how old it is has the
   * number.
   */
  linksObservedAt?: number
  models: SessionModel[]

  /**
   * What the one git read behind `links` found. Present whenever the session has a
   * working directory, including when it produced no row: `could not read` and
   * `there is none` are different sentences.
   */
  repository?: ProjectRepository
  repositoryUnreadable?: ProjectGitFailure
  session: SessionInfoSession
  usage?: SessionInfoUsage
}

/**
 * How full this conversation's context window is. The used side is counted —
 * Claude's newest parent assistant turn, or Codex's own last turn — and survives
 * a transcript too large to total, because the newest turn is at the end of the
 * file. Absent when nothing said how much fits: a Claude session on a model with no
 * window row and no status-line cache draws no reading at all, because unknown is
 * not 0%.
 */
export interface SessionInfoContext {
  /**
   * 0…100, clamped: a conversation past its window is full, not 104% full.
   */
  usedPercent: number

  /**
   * The counted used side. Absent when the only reading available was a percentage
   * somebody else worked out; also absent at exactly zero, which `usedPercent`
   * still states.
   */
  usedTokens?: number

  /**
   * How much fits — **only when the assistant itself said so** (Claude Code's
   * `context_window_size`, Codex's `model_context_window`). A window this daemon
   * guessed from the model id does not go on the wire, while `usedPercent` still
   * does: a percentage a client draws as one number is read as an approximation,
   * and `162,277 / 1,000,000 tokens` in a tooltip is read as a measurement — only
   * one of those two survives being wrong.
   */
  windowTokens?: number
}

/**
 * GET /v1/sessions/{id}/info. Kept off the session stream because answering reads
 * the session's record; the console holds an answer for a minute.
 */
export interface SessionInfoReply {
  info: SessionInfo
}

export interface SessionInfoSession {
  assistant?: Assistant
  cwd?: string
  id: string

  /**
   * The model the session is on, as its record last named it: the newest assistant
   * turn's model, or a `/model` switch made after it. Absent when the record says
   * nothing.
   */
  model?: string
  sessionId?: string

  /**
   * The same label the session list shows.
   */
  title?: string
}

/**
 * What the conversation has spent. For Claude it is the sum of every assistant turn
 * in the transcript and is absent when the transcript is larger than 8 MiB, because
 * a partial sum is not a total. For Codex it is Codex's own running total.
 */
export interface SessionInfoUsage {
  cacheRead: number
  cacheWrite: number

  /**
   * US dollars. Claude Code's own session total from its status-line cache when it
   * wrote one, otherwise these tokens at list price. Absent when neither is known,
   * which is always the case for Codex; also absent at exactly zero.
   */
  costUsd?: number
  input: number

  /**
   * The model the last counted turn named, as written.
   */
  model?: string
  output: number
  total: number
}

/**
 * One plan window, as the provider last described it.
 */
export interface SessionLimitWindow {
  /**
   * The window is spent: the provider refused a request on it, or reported 100% or
   * more.
   */
  hit: boolean

  /**
   * `5h`, `7d`, or the window's length for any other (`1d`, `90m`).
   */
  name: string

  /**
   * Unix seconds. Absent when the provider did not say.
   */
  resetsAt?: number

  /**
   * As the provider reported it, unrounded; it can exceed 100.
   */
  usedPercent: number
}

/**
 * The plan windows of the account this session's assistant runs on: an
 * account-level reading shared by every session of that assistant (the Swift app's
 * `AssistantQuota.machineLimits`), not this conversation's. An empty `windows` is
 * "nobody said", never 0%, and `unknownReason` says which kind of nothing it was.
 * It is the same reading GET /v1/orchestrator/assistants answers with, age and all,
 * so the two can never show one account two ways.
 */
export interface SessionLimits {
  /**
   * How old the provider's record is, in seconds, at the moment this answer was
   * made. Absent when nothing has been read. A percentage is drawn beside its age
   * or it reads as a number from now.
   */
  ageSeconds: number | null

  /**
   * Unix seconds of the provider record the windows came from. Absent when nothing
   * has been read.
   */
  at?: number

  /**
   * The same sentence GET /v1/orchestrator/assistants puts in `detail`: what the
   * windows say and how old they are, or which kind of nothing an empty reading
   * was.
   */
  detail?: string

  /**
   * How long this reading was good for: five percent of its shortest live window,
   * never under fifteen minutes and never over six hours. Null when there is no
   * reading to age.
   */
  freshForSeconds: number | null

  /**
   * Unix milliseconds when this daemon took the reading. A client holding readings
   * from several answers keeps the newest by this. Absent for a session with no
   * assistant.
   */
  readAtMs?: number

  /**
   * The reading is older than `freshForSeconds`, so these percentages are a lower
   * bound and not a current reading.
   */
  stale?: boolean

  /**
   * Why there is no reading, when there is none. Absent when windows were read.
   */
  unknownReason?: AssistantUnknownReason
  windows: SessionLimitWindow[]
}

/**
 * The question on a waiting session's screen, as rows a finger can hit (the Swift
 * app's menuObject). Present only on a waiting session whose screen could be read
 * as a menu; a waiting row without it is a question drawn in a shape nothing
 * recognised. The row labels and details may be refilled from the session's own
 * transcript, but only once the screen proves which question it is showing; the
 * numbers, the caret, Submit and the steps are always the screen's.
 */
export interface SessionMenu {
  options: SessionMenuOption[]

  /**
   * The prose above the rows, or the question as the call asked it. Absent when it
   * could not be read.
   */
  question?: string

  /**
   * The number of the row the caret is on. Absent when it is on none of them — a
   * multi-select's button can hold it.
   */
  selected?: number

  /**
   * Where this question sits in a set of them, as the picker's tab bar draws it.
   * Absent for a lone question.
   */
  steps?: SessionMenuStep[]
  submit?: SessionMenuSubmit
}

/**
 * One row. `n` is the keystroke and not the position: the page sends that number to
 * `POST /v1/sessions/{id}/key`, and renumbering would make a button answer a
 * different question than its label says.
 */
export interface SessionMenuOption {
  /**
   * Whether a keystroke reaches this row (1…9). A row that cannot be answered is
   * drawn and not offered.
   */
  can: boolean

  /**
   * Only on a multi-select, where a row ticks rather than answers; present and
   * false is a real answer (the daemon writes it through its own wire type, since a
   * generated optional bool would drop false).
   */
  checked?: boolean

  /**
   * The prose under the label, joined.
   */
  detail?: string
  label: string
  n: number

  /**
   * The caret is on this row, so it is what a bare Return would confirm.
   */
  selected: boolean
}

/**
 * One question of a set, as the picker's tab bar names it.
 */
export interface SessionMenuStep {
  /**
   * What was chosen, once the picker's review screen names it.
   */
  answer?: string
  done: boolean
  label: string
}

/**
 * The button under a multi-select's rows. It has no number on screen; `POST /key`
 * takes the word `submit` for it.
 */
export interface SessionMenuSubmit {
  label: string
  selected: boolean
}

/**
 * One model this session's assistant can be switched to. A session's current model
 * is matched against `id` by prefix, so a dated id still finds its row; `name` is
 * what a reader is shown for it.
 */
export interface SessionModel {
  command: string
  id: string
  name: string
}

/**
 * One assistant session. Fields that cannot be supported are absent rather than
 * invented; a reader that handles absence handles this too.
 */
export interface SessionRow {
  activity?: SessionActivity
  assistant?: Assistant
  backend: Backend
  closeability: Closeability
  coordination?: SessionCoordination
  coordinator?: SessionCoordinator
  cwd?: string
  disposition?: WorkDisposition
  evidence: Evidence
  icon?: Icon
  id: string
  identity?: IdentityBinding
  isClaude: boolean

  /**
   * What the session is called, by the Swift app's rungs (ITerm.swift
   * preferredDisplayLabel): a name typed in Clawdline (the Swift store's
   * config.json `session_titles`), the title of the task, handoff or Feature Root
   * Clawdline opened the tab for (orchestrator.json), the conversation's own title
   * (`/rename`, else `aiTitle`), Codex's thread name or an automatic title, Claude
   * Code's registry handle — the first that has something. Never a terminal
   * title. Absent when nothing names the session.
   */
  label?: string

  /**
   * What a working session says it is doing, read from its screen with the
   * assistant's own clock in it. Present while working; on a waiting session with a
   * menu it is instead that menu's revision (the Swift app's menuRevision), which
   * no row draws and which changes whenever the question does. The Swift app sends
   * it under this name and the row's height depends on it.
   */
  line?: string
  menu?: SessionMenu
  owed?: WorkOwed
  root_assignment?: RootAssignmentRecord

  /**
   * The assistant's own conversation id, when one was recovered from its command
   * line.
   */
  sessionId?: string

  /**
   * The commands this session left running in the background, newest first, at most
   * six. Absent rather than empty when there are none, as the Swift app sends it;
   * always absent for Codex, which keeps no record of them.
   */
  shells?: SessionShell[]
  state: SessionState
  tty?: string

  /**
   * Who the declaring session said will move it — a session id, or a person.
   */
  work_moved_by?: string

  /**
   * The session's own words for its state, present only when its declaration
   * decided `work_state` (then `work_provenance` is `self`).
   */
  work_note?: string

  /**
   * Whether that mover is a person. Absent unless the declaration decided the
   * state; present and false is a real answer.
   */
  work_person_needed?: boolean
  work_provenance?: WorkProvenance

  /**
   * Unix seconds: when that declaration was made.
   */
  work_since?: number
  work_state: WorkState
}

/**
 * One background command a session started and has not finished: its output file
 * has no ending written under it, and the session's transcript announced its id as
 * a background command. `at` is when it last printed something.
 */
export interface SessionShell {
  /**
   * Unix seconds.
   */
  at: number

  /**
   * The command line that started it, on one line. Absent when the two transcript
   * records it is joined from straddled a read.
   */
  command?: string

  /**
   * The last line it printed, clipped to 160 characters.
   */
  doing?: string

  /**
   * Claude Code's own id for it.
   */
  id: string

  /**
   * The description written beside the command, when there was one.
   */
  what?: string
}

/**
 * What the session appears to be doing. `unknown` is a real answer and is never
 * flattened into `idle`.
 */
export type SessionState =
    "working"
  | "waiting"
  | "idle"
  | "unknown"

export const SessionStateValues: readonly SessionState[] = ["working", "waiting", "idle", "unknown"] as const

export interface SessionsSnapshot {
  at: number
  scan: Scan
  sessions: SessionRow[]
}

/**
 * The keys to change. A null key is left as it is.
 */
export interface SettingsRequest {
  /**
   * `claude` or `codex`.
   */
  auto_name_assistant: string | null

  /**
   * 0 to 1.
   */
  backdrop: number | null

  /**
   * 0 to 1.
   */
  card_opacity: number | null

  /**
   * Whether a new session is named by an assistant.
   */
  codex_auto_name: boolean | null

  /**
   * Whether the terminal selects the tab the bar points at.
   */
  follow_target: boolean | null

  /**
   * A combination the shell can register (`cmd+shift+k`), or empty for none.
   */
  hotkey: string | null

  /**
   * `auto` or a language tag the catalog resolves.
   */
  language: string | null

  /**
   * A pack name the shell offers.
   */
  mascot: string | null

  /**
   * Whether a mascot lives in the notch.
   */
  notch: boolean | null

  /**
   * Whether an agent may push a sentence of its own.
   */
  orchestrator_agent_notify: boolean | null

  /**
   * 0, 180 or -1.
   */
  orchestrator_child_linger: number | null

  /**
   * Whether one session may hand work to another.
   */
  orchestrator_enabled: boolean | null

  /**
   * 1 to 10.
   */
  orchestrator_max_children: number | null

  /**
   * Whether a finished child types a line back into the session that sent it.
   */
  orchestrator_notify_root: boolean | null

  /**
   * `ask`, `edits` or `full`.
   */
  orchestrator_permission: string | null

  /**
   * A font family name.
   */
  output_font: string | null

  /**
   * 80 to 900.
   */
  output_height: number | null

  /**
   * `auto`, `transcript` or `terminal`.
   */
  output_mode: string | null

  /**
   * Whether the reading pane puts the newest first.
   */
  output_newest_first: boolean | null

  /**
   * 8 to 28.
   */
  output_size: number | null

  /**
   * Notify when a session reports a delivery.
   */
  push_on_delivery: boolean | null

  /**
   * Notify when a deploy ends, either way.
   */
  push_on_deploy: boolean | null

  /**
   * Notify when a whole batch of dispatched work ends.
   */
  push_on_fanout: boolean | null

  /**
   * Whether anything but this Mac may read the session list.
   */
  remote: boolean | null

  /**
   * A hostname, or empty.
   */
  remote_hostname: string | null

  /**
   * `off`, `quick` or `named`.
   */
  remote_tunnel: string | null

  /**
   * Whether a paired device may write into a session.
   */
  remote_write: boolean | null

  /**
   * Whether the bar comes back with the terminal.
   */
  reopen_on_return: boolean | null

  /**
   * Bundle identifiers separated by commas, or empty for every app.
   */
  scope_app: string | null

  /**
   * Have a model write the sentence a notification carries.
   */
  smart_notifications: boolean | null

  /**
   * `auto`, `iterm` or `tmux`.
   */
  terminal: string | null

  /**
   * `auto`, `apple` or `whisper`.
   */
  voice_engine: string | null

  /**
   * `auto`, or a language tag: letters, digits and dashes.
   */
  voice_language: string | null

  /**
   * 0 to 30.
   */
  voice_settle_seconds: number | null

  /**
   * 0 to 300.
   */
  voice_stop_seconds: number | null

  /**
   * 360 to 1400.
   */
  width: number | null

  /**
   * 0.05 to 0.80.
   */
  y_fraction: number | null
}

export interface SettingsSnapshot {
  /**
   * Whose quota that naming turn spends, `claude` or `codex`. Remembered while the
   * switch above is off, so turning it back on does not quietly change providers.
   */
  auto_name_assistant: string | null

  /**
   * How much the bar blurs what is behind it.
   */
  backdrop: number | null

  /**
   * The bar card's opacity.
   */
  card_opacity: number | null

  /**
   * Whether a new session is named by an assistant. The Swift app's spelling, kept
   * so a line copied between the two files means the same thing.
   */
  codex_auto_name: boolean | null

  /**
   * False before anything has been written. Every key then has the shell's default.
   */
  exists: boolean

  /**
   * Whether the terminal selects the tab the bar points at.
   */
  follow_target: boolean | null

  /**
   * The file's `hotkey`, or null when the file does not carry one as a string. Null
   * means the default, option+space, which the Swift app used to own and no longer
   * does; an empty string means the person asked for none, and registers nothing.
   */
  hotkey: string | null

  /**
   * `auto`, or one of the catalog's tags (`zh-Hant`, `en`, …). This build ships
   * only zh-Hant; the key is written so a later one can read it.
   */
  language: string | null

  /**
   * Which mascot pack the shell draws.
   */
  mascot: string | null

  /**
   * Whether a mascot lives in the notch.
   */
  notch: boolean | null

  /**
   * The file's `on_state_change`, the argv this app runs when a session changes
   * state. Read only here: it is an argument list, not a command line, and a single
   * text box invites exactly the word-splitting that would break a path with a
   * space in it. Absent is an empty list.
   */
  on_state_change?: string[]

  /**
   * Whether an agent may push a sentence of its own.
   */
  orchestrator_agent_notify: boolean | null

  /**
   * What becomes of a child's tab after it reports: 0 closes it, 180 waits three
   * minutes, -1 keeps it.
   */
  orchestrator_child_linger: number | null

  /**
   * Whether one session may hand work to another.
   */
  orchestrator_enabled: boolean | null

  /**
   * How many child sessions one session may run at once, 1 to 10.
   */
  orchestrator_max_children: number | null

  /**
   * Whether a finished child types a line back into the session that sent it.
   */
  orchestrator_notify_root: boolean | null

  /**
   * How far a child may go on its own: `ask`, `edits` or `full`.
   */
  orchestrator_permission: string | null

  /**
   * The reading pane's face. Monospaced, because the pane draws a terminal.
   */
  output_font: string | null

  /**
   * The reading pane's height in points.
   */
  output_height: number | null

  /**
   * What the reading pane shows: `auto`, `transcript` or `terminal`.
   */
  output_mode: string | null

  /**
   * Whether the reading pane puts the newest first.
   */
  output_newest_first: boolean | null

  /**
   * The reading pane's text size in points.
   */
  output_size: number | null

  /**
   * Where the file is, whether or not it exists.
   */
  path: string

  /**
   * Notify when a session reports a delivery.
   */
  push_on_delivery: boolean | null

  /**
   * Notify when a deploy ends, either way.
   */
  push_on_deploy: boolean | null

  /**
   * Notify when a whole batch of dispatched work ends.
   */
  push_on_fanout: boolean | null

  /**
   * Whether anything but this Mac may read the session list.
   */
  remote: boolean | null

  /**
   * The hostname a named tunnel answers on.
   */
  remote_hostname: string | null

  /**
   * `off`, `quick` or `named`.
   */
  remote_tunnel: string | null

  /**
   * Whether a paired device may write into a session.
   */
  remote_write: boolean | null

  /**
   * Whether the bar comes back with the terminal.
   */
  reopen_on_return: boolean | null

  /**
   * The file's `scope_app`, or null when absent — which the shell reads as
   * com.googlecode.iterm2. Empty is every app.
   */
  scope_app: string | null

  /**
   * Have a model write the sentence a notification carries.
   */
  smart_notifications: boolean | null

  /**
   * Where a new session opens: `auto`, `iterm` or `tmux`. Not the same question as
   * scope_app.
   */
  terminal: string | null

  /**
   * `auto`, `apple` or `whisper`.
   */
  voice_engine: string | null

  /**
   * What whisper reads a recording as: `auto`, which follows `language`, then this
   * machine's languages, then the shipped catalog — or a tag such as `zh-Hant`,
   * `zh-Hans` or `en`.
   */
  voice_language: string | null

  /**
   * How long a pause ends a sentence. 0 is off.
   */
  voice_settle_seconds: number | null

  /**
   * How long a silence ends the whole turn. 0 is off.
   */
  voice_stop_seconds: number | null

  /**
   * The bar's width in points.
   */
  width: number | null

  /**
   * Where the bar's top sits, as a fraction of screen height.
   */
  y_fraction: number | null
}

/**
 * Whether the task has written a result yet. `settled` false is not a failure; it
 * means nothing has been written, which is the ordinary state of work still in
 * progress.
 */
export interface SettleResult {
  ok: boolean
  settled: boolean
  state?: TaskState
  task_id: string
}

/**
 * A new or adopted token, twice: here for a script, and in `Set-Cookie:
 * clawdline-next=…; Path=/; Max-Age=31536000; HttpOnly; SameSite=Strict` (plus `;
 * Secure` behind an HTTPS proxy) for a page.
 */
export interface SignedIn {
  ok: boolean
  token: string
}

/**
 * Where a skill came from. Claude's are read from `.claude/skills` in the project
 * (from the repository root down to the working directory), `~/.claude/skills` and
 * installed plugins; Codex's are the catalog its rollout was started with, where
 * `admin` and `system` can also appear.
 */
export type SkillSource =
    "project"
  | "personal"
  | "plugin"
  | "admin"
  | "system"

export const SkillSourceValues: readonly SkillSource[] = ["project", "personal", "plugin", "admin", "system"] as const

/**
 * The effective list, sorted by name, after the precedence a typed command follows:
 * a personal skill replaces a project skill of the same name, a deeper project
 * directory replaces an ancestor, and `skillOverrides: off` takes one out. Held for
 * five minutes per working directory and assistant, as the Swift app holds it;
 * `observedAt` says how old the reading is.
 */
export interface SkillsReply {
  /**
   * When this list was read, in seconds since 1970.
   */
  observedAt: number
  skills: AssistantSkill[]

  /**
   * More skills were found than one answer carries, and the rest are not in
   * `skills`. Absent when nothing was left out.
   */
  truncated?: boolean
}

/**
 * What one source's answer is worth, and the four are not degrees of the same
 * thing. `current`: read in full just now, and nothing in it rests on an older
 * reading. `stale`: read, and known to be short — some part of it could not be
 * reached, so what is here is less than what there is. `missing`: it could not be
 * read at all, which is never the same as it being empty. `unverified`: read in
 * full, and a fact in it rests on something this daemon cannot confirm still holds
 * — the answer exists and may already be out of date. The fourth word exists
 * because the first three only ever measured whether the reading happened. A ledger
 * that reads its own records perfectly and cannot say whether the work they
 * describe has since landed was answering `current` about a fact it had no way to
 * check, and a screen drew that as settled. A reader may print an `unverified`
 * count; it may never print it as a certainty, and it may never draw any of the
 * last three as `0`.
 */
export type SourceFreshness =
    "current"
  | "stale"
  | "missing"
  | "unverified"

export const SourceFreshnessValues: readonly SourceFreshness[] = ["current", "stale", "missing", "unverified"] as const

export interface StartAssistant {
  availability: StartAvailability
  id: string
  label: string
}

/**
 * AssistantQuota.Availability. This daemon reads no quota, so it answers unknown.
 */
export type StartAvailability =
    "ok"
  | "low"
  | "exhausted"
  | "unknown"

export const StartAvailabilityValues: readonly StartAvailability[] = ["ok", "low", "exhausted", "unknown"] as const

/**
 * One directory a session can be started in. `id` is sixteen hex characters of the
 * path's SHA-256 and is the only part a client sends back; `path` is here so two
 * projects with one name can be told apart.
 */
export interface StartPlace {
  /**
   * When this place was last worked in, Unix seconds.
   */
  at: number
  icon?: Icon
  id: string
  label: string
  path: string
}

/**
 * GET /v1/places: recorded Claude Code folders, Codex rollouts and live sessions'
 * directories, deduplicated, still on disk, newest first, at most forty.
 */
export interface StartPlaceList {
  assistants: StartAssistant[]
  at: number
  places: StartPlace[]
}

/**
 * Whether the Swift app's store was read for this answer: `current`; `stale`, an
 * earlier reading carried because the newest one was half-written; `unknown`,
 * nothing could be read; `absent`, there is no Swift store on this machine; or
 * `disabled`, this daemon was told not to read it (CLAWDLINE_NEXT_LEGACY_STORE=off,
 * cutover B1). Unknown is never the same as empty; absent and disabled are known,
 * and the list is then this daemon's own tasks only.
 */
export type StoreReading =
    "current"
  | "stale"
  | "unknown"
  | "absent"
  | "disabled"

export const StoreReadingValues: readonly StoreReading[] = ["current", "stale", "unknown", "absent", "disabled"] as const

/**
 * One stored picture and the literal to paste into a reply to show it:
 * `<clawdline-image id="…">`.
 */
export interface StoredImage {
  byte_count: number
  expires_at: number
  height: number
  id: string
  marker: string
  media_type: string
  width: number
}

/**
 * The tab the task was opened in.
 */
export interface TaskChild {
  backend?: string
  sessionId?: string
  terminalId?: string
}

/**
 * `at` is when the answer was built. With `store` at `unknown` the list holds only
 * this daemon's own tasks, which is not the same as the machine having no others.
 */
export interface TaskList {
  at: number
  page: TaskPage

  /**
   * What this list is worth as a reading, in the one vocabulary every source on
   * this daemon answers in. `store` says how the Swift app's store was read; this
   * says what that makes of the whole answer, so a screen can print the list's
   * freshness without knowing which stores it came from. `stale` when the Swift
   * store could not be read at all — the list is then this daemon's own tasks and
   * is short by however many the other store held; `unverified` when an earlier
   * reading of it was carried, so the rows are here and a row may have moved since;
   * `current` otherwise, which includes a machine with no Swift store, because
   * absent is known.
   */
  source: BearingsSource
  store: StoreReading
  tasks: TaskRow[]
}

/**
 * Which finished tasks this answer carries. Unfinished ones ride on every page.
 */
export interface TaskPage {
  cursor: number
  fields: string
  finished: number
  limit: number

  /**
   * Where the next page starts. The Swift app sends null on the last page; here the
   * key is absent.
   */
  nextCursor?: number
  unfinished: number
}

/**
 * The session that asked for the task. `terminalId` is not stored: it is resolved
 * on every read against the sessions on screen — the parent task's child terminal
 * first, otherwise the one live session whose conversation is `sessionId` — and
 * is absent when that is not exactly one.
 */
export interface TaskRoot {
  assistant?: string
  label?: string
  sessionId?: string
  taskId?: string
  terminalId?: string
}

/**
 * One task. The camelCase keys are the Swift app's list projection, which the
 * copied console reads (`view/derive.js`: id, title, state, created, finishedAt,
 * child, root, usage). The four snake_case keys `task_id`, `project_dir`,
 * `created_at` and `claims` are this daemon's older names, kept beside them because
 * the Dashboard panel still reads them. The Swift app's `projectDir` is sent only
 * as `project_dir`: the generator gives both spellings one Go name, and the copied
 * console reads neither. `claims` is therefore always present here, where the Swift
 * app leaves it out when none were declared (`claims_declared` says which). Omitted
 * from the Swift projection because no page here reads them: worktree (its presence
 * is `isolation`), executor, completion_delivery, verification, landing,
 * landing_paths, terminal_intervention, released_claims, respawn_of, waiting_on.
 */
export interface TaskRow {
  artifacts?: string[]
  assistant: Assistant
  attachSession?: string
  attached?: boolean
  briefedAt?: number
  child?: TaskChild
  claims: string[]
  claims_declared: boolean

  /**
   * Unix seconds.
   */
  created: number

  /**
   * Unix seconds; the same instant as `created`.
   */
  created_at: number
  depth: number
  dir: string
  finishedAt?: number
  id: string
  isolation?: string
  kind: string
  model?: string
  permission: string
  project_dir: string
  reasoning_effort?: string
  resultVerifiedAt?: number
  root?: TaskRoot
  schedule_id?: string
  session_root?: boolean
  spawnedAt?: number
  state: TaskState
  task_id: string
  title: string
  untouched_claims?: string[]
  usage?: TaskUsage
  workItemId?: string
  workPhase?: string
}

/**
 * Where a task is. `unreadable` is not a state a task moves through: it is a stored
 * row this daemon wrote and cannot decode, listed as such because it is not absent
 * — its id is taken, and a dispatch reusing it is refused (409
 * `task_unreadable`).
 */
export type TaskState =
    "queued"
  | "spawning"
  | "briefed"
  | "success"
  | "failure"
  | "timeout"
  | "cancelled"
  | "spawn_failed"
  | "unreadable"

export const TaskStateValues: readonly TaskState[] = ["queued", "spawning", "briefed", "success", "failure", "timeout", "cancelled", "spawn_failed", "unreadable"] as const

/**
 * What the child spent. `costUsd` is absent where nothing priced it, which is
 * always the case for Codex.
 */
export interface TaskUsage {
  cacheRead: number
  cacheWrite: number
  costUsd?: number
  input: number
  model?: string
  output: number
  total: number
}

/**
 * The entry bound, on the wire where a reader can see it (timeline-design A4). What
 * is dropped at the bound is the oldest, and it is a projection of records this
 * daemon still holds, so nothing is lost by dropping it.
 */
export interface TimelineCapacity {
  entryCount: number
  entryLimit: number
}

/**
 * What kind of work an entry was. `feature` for ordinary delivery, `operation` for
 * a task whose write set was only tooling or documentation.
 */
export type TimelineCategory =
    "feature"
  | "operation"

export const TimelineCategoryValues: readonly TimelineCategory[] = ["feature", "operation"] as const

/**
 * How far one Project's history has been read. It is derived on every read and
 * stored nowhere, so it can never freeze the way a saved cursor did.
 */
export interface TimelineCheckpoint {
  historyStatus: TimelineHistoryStatus
  projectId: string
}

/**
 * One delivery. The id is the broker task's, because the task is the thing that was
 * delivered and an id of this projection's own invention would be a second name for
 * it.
 */
export interface TimelineEntry {
  /**
   * The work items this delivery is on, as the task's own `work_id` names them.
   */
  boardItemIds: string[]
  events: TimelineEvent[]
  id: string

  /**
   * The task's own title, never a summary written for it.
   */
  originalTitle: string
  primaryCategory: TimelineCategory
  projectId: string
  projection: TimelineProjection
  sourceRevisions: TimelineRevision[]

  /**
   * The delivery's own one-paragraph account of itself, cut to a length the card
   * can hold. Absent when the task wrote none.
   */
  summary?: string
}

export interface TimelineEnvelope {
  timeline: TimelineSnapshot
}

/**
 * One piece of evidence under an entry, and who said it. `authority` is what wrote
 * it down — `broker` for this daemon's own landing record — because an event
 * with no authority is an assertion.
 */
export interface TimelineEvent {
  authority: string

  /**
   * Unix seconds: when the thing happened. Absent when only the observation time is
   * known.
   */
  effectiveAt?: number
  kind: string

  /**
   * Unix seconds: when this Mac learned of it.
   */
  observedAt: number
  result: string
}

/**
 * How far back this Project's coverage reaches. `unknown` is the honest answer
 * while no history importer exists; `capacity` is the entry bound reached, and what
 * was retained is never removed to make room.
 */
export type TimelineHistoryStatus =
    "complete"
  | "capacity"
  | "unknown"

export const TimelineHistoryStatusValues: readonly TimelineHistoryStatus[] = ["complete", "capacity", "unknown"] as const

export interface TimelineProject {
  id: string

  /**
   * The repository's own name. Never a reconstruction of one this Mac no longer
   * holds.
   */
  label: string
  name?: string
}

/**
 * What the events below add up to. `availableTargets` is how many targets this
 * entry is proved available on, which on this daemon is always zero: there is no
 * deployment evidence producer, and a required target nothing can answer is not the
 * same as a failure.
 */
export interface TimelineProjection {
  availableTargets: number

  /**
   * Unix seconds. Absent when nothing under this entry carried one.
   */
  effectiveAt?: number
  observedAt: number
  requiredTargets: number
  status: TimelineStatus
}

/**
 * One commit an entry rests on, as the landing record proved it. `githubUrl` only
 * when the repository is a GitHub one this daemon can name with certainty.
 */
export interface TimelineRevision {
  commit: string
  githubUrl?: string
  repositoryId: string
  shortCommit: string
}

export interface TimelineSnapshot {
  capacity: TimelineCapacity
  checkpoints: TimelineCheckpoint[]
  enabled: boolean
  entries: TimelineEntry[]

  /**
   * A keyset cursor — the last entry's time and id — not an offset, so a page
   * that arrives while records are being written cannot skip an entry
   * (timeline-design A5). Absent on the last page.
   */
  nextCursor?: string
  project: TimelineProject

  /**
   * The reading's own counter. It changes when the records under it do; nothing
   * writes to this projection, so it is never a compare-and-set token.
   */
  revision: number
  selected?: TimelineEntry

  /**
   * `current`, or `partial` when one of the sources under this reading could not be
   * read — never an empty list drawn as a quiet Project.
   */
  status: string
  viewer: TimelineViewer
}

/**
 * What this Mac can prove about one entry. Only the three this daemon can reach are
 * here: the Swift app's other nine name deployment outcomes, and a word no producer
 * can ever write is a promise the screen cannot keep (design-decisions X25).
 */
export type TimelineStatus =
    "landed_to_git"
  | "upcoming"
  | "unknown"

export const TimelineStatusValues: readonly TimelineStatus[] = ["landed_to_git", "upcoming", "unknown"] as const

export interface TimelineViewer {
  /**
   * False on this daemon, always: the Timeline is a projection of records it
   * already keeps, so there is no switch to turn it off and nothing a viewer could
   * manage.
   */
  canManage: boolean
}

export interface TranscriptAction {
  command?: string

  /**
   * read or search.
   */
  kind: string
  name?: string
  path?: string
  query?: string
}

/**
 * What a Codex tool item recorded about itself: `called` for an MCP call with a
 * title, `explored` for a shell command Codex classified as reads and searches.
 */
export interface TranscriptActivity {
  actions: TranscriptAction[]

  /**
   * How long the item took. -1 when the record did not say, which the Swift app
   * sends as an absent key; 0 is a real, sub-millisecond duration and is drawn as
   * one.
   */
  durationMs: number
  kind: string

  /**
   * A called tool's result text, cut at 4,000 characters.
   */
  result?: string

  /**
   * inProgress, pending, completed or failed.
   */
  status?: string
  title?: string
}

/**
 * One thing in a conversation, in the shape the Swift app's `transcriptRows` writes
 * it. A tool call and what the tool returned both carry `role: tool`; only the call
 * names its tool. A call's `text` is the one line describing what it was asked to
 * do — a command, a path, a query — which is what a folded row shows as its
 * subject. An `AskUserQuestion` call carries its questions instead, after the
 * U+0001 `ask` U+0001 marker.
 */
export interface TranscriptEntry {
  activity?: TranscriptActivity

  /**
   * Pictures an assistant turn showed with a `<clawdline-image>` marker, or a
   * Clawdline session message carried. Resolved against this daemon's store and
   * then, read-only, the Swift app's.
   */
  artifacts?: ImageArtifact[]

  /**
   * Unix seconds. Absent when the record carried no timestamp this reader accepts.
   */
  at?: number

  /**
   * Exact edits: a Codex patch, or the whole file a Claude `Write` created. Absent
   * on every other entry.
   */
  fileChanges?: TranscriptFileChange[]

  /**
   * Images attached to a user turn. Absent when there were none: the Swift app
   * writes an explicit 0 on user rows, and a reader treats absence as that 0.
   */
  imageCount?: number
  notice?: TranscriptNotice

  /**
   * A complete Codex checklist update.
   */
  plan?: TranscriptPlanStep[]

  /**
   * user, assistant, peer (another Claude Code session), message (another session
   * through Clawdline), notice (Clawdline about a task) or tool.
   */
  role: string

  /**
   * The human-facing name of the session a peer or message row came from.
   */
  source?: string

  /**
   * Which assistant sent a Clawdline session message.
   */
  sourceAssistant?: string

  /**
   * How a peer or message row arrived: the peer's own mode, or `clawdline`.
   */
  sourceMode?: string
  text: string

  /**
   * The tool a call used. Absent on a tool's result and on prose.
   */
  tool?: string
}

export interface TranscriptFileChange {
  /**
   * The whole file, for an addition, a deletion or a Claude `Write`.
   */
  content?: string

  /**
   * add, delete, update or write, as the record spelled it; `change` when it did
   * not.
   */
  kind: string
  movePath?: string
  path: string
  unifiedDiff?: string
}

/**
 * A decoded Clawdline notice without its protocol, version and body — the Swift
 * app's `webObject`. Which fields are present depends on `kind`: task_finished,
 * workspace_overlap, file_wait_request, file_wait_release or handoff_receipt.
 */
export interface TranscriptNotice {
  ack_path?: string
  assistant?: string
  audience?: string

  /**
   * Present only when true.
   */
  child_may_still_write?: boolean

  /**
   * Present only when true.
   */
  claims_released?: boolean
  commit?: string
  handoff_id?: string
  kind: string
  note?: string
  notice_id?: string

  /**
   * task_finished only, where the decoder requires it, so absence there means 0.
   */
  outstanding?: number
  overlaps?: TranscriptNoticeOverlap[]
  paths?: string[]
  project_dir?: string
  reason?: string
  release_condition?: string
  repository?: string
  result_path?: string
  state?: string
  task?: TranscriptNoticeTask
  title?: string
  wait_id?: string
  waiter_session_id?: string
}

export interface TranscriptNoticeOverlap {
  path: string
  task: TranscriptNoticeTask
}

export interface TranscriptNoticeTask {
  id: string
  title: string
}

/**
 * `entries`, `signature` and `truncation` are the Swift app's transcript payload;
 * `evidence`, `path` and `note` say where the reading came from; `unread` is this
 * daemon's own, and says the read window stopped short of the conversation's start.
 */
export interface TranscriptPage {
  /**
   * Oldest first.
   */
  entries: TranscriptEntry[]
  evidence: Evidence
  id: string
  note?: string

  /**
   * Which file this was read from. A reading that cannot name its source is not
   * evidence.
   */
  path?: string

  /**
   * The record's size and modification time, `<bytes>-<unix seconds>`, and empty
   * when nothing was read. It changes whenever the entries could have.
   */
  signature: string
  truncation?: TranscriptTruncation
  unread?: TranscriptUnread
}

export interface TranscriptPlanStep {
  /**
   * pending, inProgress or completed — Codex app-server's spelling, not the
   * rollout's in_progress.
   */
  status: string
  step: string
}

/**
 * The newest entries were kept and older ones left out, because the whole page
 * would have passed its byte budget.
 */
export interface TranscriptTruncation {
  budgetBytes: number
  entriesOmittedCount: number

  /**
   * transcript_byte_budget.
   */
  reason: string
}

/**
 * This read looked at only the newest `windowBytes` of the record and ran out of
 * them before it had as many entries as were asked for, so the conversation goes
 * back further than the first entry here: `bytes` older bytes were not read at all.
 * The Swift app cuts the same window and says nothing; this is the flag it lacks
 * (docs/limits.md N17), so a page drawn from it can say that older content was not
 * loaded instead of looking complete.
 */
export interface TranscriptUnread {
  /**
   * How many bytes before the window were not read. Always more than zero.
   */
  bytes: number

  /**
   * transcript_read_window.
   */
  reason: string

  /**
   * How much of the record's end one read looks at.
   */
  windowBytes: number
}

/**
 * `off`; `quick`, an address made up per run under trycloudflare.com; `named`, the
 * person's own tunnel (`remote_tunnel_name`) and hostname (`remote_hostname`).
 */
export type TunnelMode =
    "off"
  | "quick"
  | "named"

export const TunnelModeValues: readonly TunnelMode[] = ["off", "quick", "named"] as const

/**
 * `off`; `starting`, launched or waiting to retry and not yet registered with the
 * edge; `up`; `failed`, with a reason — including a refusal to start.
 */
export type TunnelState =
    "off"
  | "starting"
  | "up"
  | "failed"

export const TunnelStateValues: readonly TunnelState[] = ["off", "starting", "up", "failed"] as const

/**
 * One reading of the tunnel.
 */
export interface TunnelStatus {
  at: number

  /**
   * Launches in a row that have died, while it is retrying; absent when none have.
   */
  attempts?: number

  /**
   * The cloudflared the next launch would run: `cloudflared_path` when it is set
   * and executable, else where a package manager puts it, else PATH. Absent when
   * there is none.
   */
  binary?: string

  /**
   * When state, url or reason last moved.
   */
  changed: number

  /**
   * The command line of the child that is running or was last started, binary
   * first. It always carries `--config` and this daemon's own file, never the
   * person's ~/.cloudflared/config.yml.
   */
  command?: string[]

  /**
   * The configuration file cloudflared is pointed at, in this daemon's state
   * directory.
   */
  config: string
  installed: boolean
  mode: TunnelMode

  /**
   * Why it failed or refused, in the tunnel's own sentence. Present when state is
   * failed.
   */
  reason?: string
  state: TunnelState

  /**
   * The address, once a connection to Cloudflare's edge is registered. Present when
   * state is up.
   */
  url?: string
}

/**
 * The Swift app's `UsageQueryService` payload. The lossless `.json` export is this
 * object unwrapped, with every matched row, `truncated`, and no `pagination`.
 */
export interface UsageAnalytics {
  availability: AnalyticsAvailability
  breakdown: AnalyticsBreakdown[]
  bucket: string
  capabilities: AnalyticsCapabilities
  corrections: number
  coverage: AnalyticsCoverageSummary
  freshness: AnalyticsFreshness
  groupBy: string
  pagination?: AnalyticsPagination
  portfolio: AnalyticsPortfolio
  priceSnapshot: AnalyticsPriceSnapshot
  range: AnalyticsRange
  rangeFreshness: AnalyticsRangeFreshness
  rowCount: number
  rows: AnalyticsRow[]
  schemaVersion: number
  source?: AnalyticsSource
  totals: AnalyticsSummary
  trend: AnalyticsTrendBucket[]

  /**
   * The `.json` export only.
   */
  truncated?: boolean
  unavailableDimensions: AnalyticsUnavailableDimensions

  /**
   * overview or agent_work; echoed only.
   */
  view: string
}

/**
 * A refused Usage read.
 */
export interface UsageAnalyticsRefusal {
  error: UsageAnalyticsRefusalBody
}

/**
 * The Swift app's refusal envelope, which the Usage page reads its code from.
 * Codes: bad_request, usage_analytics_busy (503, with Retry-After),
 * export_too_large (413), json_serialization_failed, ambiguous_project (409),
 * project_not_found (404).
 */
export interface UsageAnalyticsRefusalBody {
  code: string
  message: string
  request_id: string
}

/**
 * GET /v1/orchestrator/usage/analytics.
 */
export interface UsageAnalyticsReply {
  usage: UsageAnalytics
}

export interface UsageReport {
  at: number
  sessions: UsageRow[]

  /**
   * The sum of the rows that could be read. Rows carrying `evidence: none`
   * contribute nothing, so this can be smaller than the truth and never larger.
   */
  totalTokens: number
}

/**
 * One session's usage, as its own transcript records it. This is what the
 * transcript accounts for, which is a smaller claim than what the session spent:
 * one conversation's own turns cannot see work another model did on its behalf.
 */
export interface UsageRow {
  assistant?: Assistant
  evidence: Evidence
  id: string
  label?: string

  /**
   * How many assistant turns were counted. Absent for a source that reports a
   * cumulative total rather than per-turn figures.
   */
  messages?: number
  models: ModelUsage[]

  /**
   * Why a row could not be read. Present with `evidence: none`, and never alongside
   * a number.
   */
  note?: string
  totalTokens: number
}

/**
 * The whole answer. `features` and `unattributed` are the list read; `feature` is
 * the one-Feature read and is absent from the list read.
 */
export interface VerificationLedger {
  feature?: LedgerFeature
  features: LedgerFeature[]
  read: LedgerRead

  /**
   * The rows and receipts that name no Feature, drawn above every Feature and
   * inside none of them: every figure below it is short by exactly this much. Null
   * when there are none.
   */
  unattributed: LedgerFeature | null
}

export interface VerificationLedgerEnvelope {
  verificationLedger: VerificationLedger
}

/**
 * GET /v1/voice/language: what the next recording will be read as, and who said so.
 * `auto` follows Clawdline's own language (the `language` setting), then this
 * machine's languages, then the catalog this daemon ships; the settings window says
 * the answer back, so a Simplified transcript is never a surprise nobody could have
 * seen coming.
 */
export interface VoiceLanguage {
  /**
   * What whisper is given as `-l`: `zh`, another two-letter code, or `auto` for
   * whisper's own detection.
   */
  code: string

  /**
   * How Chinese in the answer is written: `Hant`, `Hans`, or empty when nothing
   * said, which is whisper's own habit and Simplified.
   */
  script: string

  /**
   * Who decided `script`, in the same words as `source`; empty when nobody did.
   */
  script_source: string

  /**
   * The tag that decided `script`.
   */
  script_tag: string

  /**
   * `voice_language` as the settings file has it: `auto`, or a tag.
   */
  setting: string

  /**
   * Who decided `code`: `voice_language`, `language`, `AppleLanguages`,
   * `AppleLocale`, `LANGUAGE`, `LC_ALL`, `LC_MESSAGES`, `LANG`, `Windows`,
   * `catalog`, or empty when nobody did.
   */
  source: string

  /**
   * The tag that source gave, as it spelled it.
   */
  tag: string
}

/**
 * A refusal from this route. It is the ordinary refusal shape with one field added,
 * because `no_whisper` covers two different afternoons: `brew install whisper-cpp`
 * leaves a machine with the binary and no model, and a page told only "no whisper"
 * sends somebody to check the thing they already did.
 */
export interface VoiceRefusal {
  detail: string
  error: string

  /**
   * Only on `no_whisper`: `no_binary` or `no_model`.
   */
  reason?: string
}

/**
 * A recording, already in the one shape whisper.cpp takes. The resampling is done
 * in the browser because that is the one format question every browser can answer
 * about itself — what it just recorded — while this machine has no ffmpeg and
 * could not open an Opus file if it wanted to.
 */
export interface VoiceRequest {
  /**
   * Base64 of little-endian 16-bit mono PCM. A minute of it is about 2.6MB encoded.
   */
  audio: string

  /**
   * Must be 16000. Checked rather than resampled: a body that names 48000 has not
   * made a small mistake, it has sent something that would transcribe as a voice
   * three times too fast, and quietly resampling somebody's voice is a worse answer
   * than saying no.
   */
  rate: number
}

/**
 * What was said, and how long this machine took to read it. An empty `text` is an
 * answer and not a failure: whisper heard the recording and there were no words in
 * it, which happens to a pocket and to a room that went quiet.
 */
export interface VoiceResult {
  ms: number
  text: string
}

